	*a = a.Mul(b)
}

func (a ModInt) Neg() ModInt {
	if a.v == 0 {
		return ModInt{0}
	}
	return ModInt{MOD - a.v}
}

func NewModInt(n uint32) ModInt {
	return ModInt{n % MOD}
}

func ModZero() ModInt {
	return ModInt{0}
}

func ModOne() ModInt {
	return ModInt{1}
}

