				}
				for i := 0; i <= c; i++ {
					next[i].AddAssign(dp[i].Mul(pc.Inv(i + 1)))
				}
				for i := c - 1; i >= 0; i-- {
					next[i] = next[i].Add(next[i+1])
				}
				dp = next
			}
			s := ModZero()
